 1	import { spawn } from 'node:child_process';
 2	
 3	/**
 4	 * Launches an external application as a detached, fire-and-forget child
 5	 * process.  The spawned process is fully decoupled from the Node.js process:
 6	 * it runs with `detached: true` and `stdio: 'ignore'` so it continues living
 7	 * independently even if the parent exits.
 8	 *
 9	 * Cross-platform notes:
10	 * - On **Windows** (`process.platform === 'win32'`), `shell: true` is used so
11	 *   that `.cmd` / `.bat` launchers (e.g. `code.cmd`) are found on PATH and
12	 *   executed correctly by the Windows shell.
13	 * - On all other platforms, `shell: false` is used for direct process
14	 *   execution without an intermediate shell.
15	 *
16	 * @param command - The executable to launch (e.g. `"code"`, `"github"`).
17	 * @param args    - Command-line arguments to pass to the executable.
18	 * @returns A promise that resolves once the child process has been successfully
19	 *   spawned, or rejects with a descriptive error if spawning fails.
20	 * @throws {Error} If `command` is empty or blank — message:
21	 *   `'Failed to launch application: command must not be empty.'`
22	 * @throws {Error} If the OS-level spawn fails (e.g. command not found) — message
23	 *   format: `'Failed to launch application "<command>": <os-error-message>'`
24	 */
25	export function launchApplication(command: string, args: string[]): Promise<void> {
26	    return new Promise<void>((resolve, reject) => {
27	        // Guard against empty command strings early. Node's spawn() throws
28	        // synchronously for empty filenames, which would bypass the Promise-
29	        // wrapped `error` event handler and produce an inconsistently formatted
30	        // rejection.  Failing fast here keeps rejection behaviour uniform for
31	        // all invalid inputs.
32	        if (!command.trim()) {
33	            reject(new Error('Failed to launch application: command must not be empty.'));
34	            return;
35	        }
36	
37	        const useShell = process.platform === 'win32';
38	
39	        const child = spawn(command, args, {
40	            shell: useShell,
41	            detached: true,
42	            stdio: 'ignore',
43	        });
44	
45	        // `unref()` lets the parent exit without waiting for this child.
46	        child.unref();
47	
48	        child.on('spawn', () => {
49	            resolve();
50	        });
51	
52	        child.on('error', (err: Error) => {
53	            reject(
54	                new Error(
55	                    `Failed to launch application "${command}": ${err.message}`,
56	                ),
57	            );
58	        });
59	    });
60	}

