55	function mockRequest(method: string, url: string): IncomingMessage {
56	    const req = new EventEmitter() as IncomingMessage;
57	    (req as unknown as { method: string }).method = method;
58	    (req as unknown as { url: string }).url = url;
59	    (req as unknown as { destroy(): void }).destroy = () => {
60	        req.emit('error', new Error('destroyed'));
61	    };
62	    process.nextTick(() => {
63	        req.emit('end');
64	    });
65	    return req;
66	}
