68	interface MockResponse {
69	    statusCode: number | undefined;
70	    headers: Record<string, string | number>;
71	    body: string;
72	    res: ServerResponse;
73	}
74	
75	function mockResponse(): MockResponse {
76	    const mock_: MockResponse = {
77	        statusCode: undefined,
78	        headers: {},
79	        body: '',
80	        res: null as unknown as ServerResponse,
81	    };
82	    const res = new EventEmitter() as unknown as ServerResponse;
83	    (res as unknown as {
84	        writeHead(status: number, headers: Record<string, string | number>): void;
85	    }).writeHead = (status: number, headers: Record<string, string | number>) => {
86	        mock_.statusCode = status;
87	        mock_.headers = { ...headers };
88	    };
89	    (res as unknown as { end(body: string): void }).end = (body: string) => {
90	        mock_.body = body;
91	    };
92	    mock_.res = res;
93	    return mock_;
94	}
